SELECT DISTINCT cs.canonical_smiles, cr_sub.compound_name AS substrate_compound_name, cr_par.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m LEFT JOIN compound_records cr_sub ON m.substrate_record_id = cr_sub.record_id LEFT JOIN compound_records cr_par ON m.drug_record_id = cr_par.record_id LEFT JOIN molecule_dictionary md ON cr_sub.molregno = md.molregno LEFT JOIN compound_structures cs ON md.molregno = cs.molregno WHERE m.enzyme_name = 'UGT1A9' ORDER BY cs.canonical_smiles, cr_sub.compound_name, cr_par.compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name LIMIT 200
